  _ = `Esemény szerkesztése`,
  _ = `Fő grafika`,
  _ = `Helyezz el nagy márkaképet eseményed vagy bejelentésed tetején`,
  _ = `Húzz ide képet lentről a beállításához, vagy használd a választót új képek feltöltéséhez`,
