  _ = `Láthatóság`,
  _ = `Szakaszcím`,
  _ = `Válassz az e szakasz tetején megjelenítendő, előre lefordított címek listájából, vagy válaszd az „egyedi cím” lehetőséget saját cím beírásához. Egy előre lefordított cím megtalálásához kezdj el gépelni a mezőbe.`,
  _ = `Alcím`,
  _ = `(Maximum %1$s karakter. Az esemény vagy bejelentés részletek oldalának tetején jelenik meg.)`,
  _ = `(A maximális %1$s karakterszám elérve. Az esemény vagy bejelentés részletek oldalának tetején jelenik meg.)`,
  _ = `A v2 készítői kezdőoldalak rugalmas módot kínálnak a kiadói, fejlesztői vagy franchise oldalad testreszabására.`,
  _ = `Ez az oldal nem látható. Először tedd közzé ezt az oldalt, majd be tudod állítani, hogy ez legyen a jelenlegi készítői kezdőoldalad.`,
  _ = `Ez az oldal <1>nem</1> a jelenlegi készítői kezdőoldalad. Használd a <2>készítői kezdőoldali műszerfaladat</2> ennek aktiválásához.`,
  _ = `Ez az oldal a jelenlegi készítői kezdőoldalad. Ezt a <1>készítői kezdőoldali műszerfaladon</1> tudod kezelni.`,
  _ = `Avatár`,
  _ = `Szerkesztés: <1>Készítői kezdőoldal szerkesztő</1>`,
  _ = `Szlogen`,
  _ = `Szerkesztés: <1>Készítői kezdőoldali műszerfal</1>`,
  _ = `Üdv!`,
  _ = `<1>A játékaid</1> – A játékaid szerepelnek az alábbi kapcsolt alkalmazáslistában, és használatra készek. Csak add hozzá és konfiguráld az alábbi szakaszokat, hogy játékaidat, DLC-idet, demóidat és zenei anyagaidat a szükségleteidnek legmegfelelőbb módon árusítsd.`,
  _ = `<1>További játékok kapcsolása</1> – Ha e listából hiányoznak játékok, az azt jelenti, hogy nem kapcsoltad össze azokat e készítői kezdőoldallal. Útmutatásért a játékok kezdőoldaladhoz kapcsolásáról, kérjük, nézd meg a <2>Fejlesztői és kiadói kezdőoldalak</2> dokumentációt.`,
  _ = `<1>Alapértelmezett beállítás</1> – Alább találni fogsz egy sor alapértelmezett szakaszt, amelyek már úgy vannak beállítva, hogy kiemeljék a népszerű, javasolt és közelmúltbeli megjelenéseidet. Nyugodtan használd az alapértelmezetteket kívánság szerint, amilyen mértékben szeretnéd.`,
  _ = `További részletekért nézd meg a dokumentációt.`,
  _ = `Kategória: %1$s`,
  _ = `Eseményklónozási hiba`,
  _ = `Hibába ütköztünk a klónozásra való felkészülés folyamatának során: %1$s`,
  _ = `Esemény-közzétételi hiba`,
  _ = `Hibába ütköztünk az esemény közzétételére való felkészülés folyamata során: %1$s`,
  _ = `Ehhez a vásárhoz egy hosszú tétellista van kapcsolva, ezért a tárgycímkéi újra lesznek építve az Áruházból. Ez eltarthat egy ideig.`,
  _ = `Nem tudtuk újraépíteni e vásár tárgycímkéit az Áruházból, így a szerkesztő nem nyitható meg biztonságosan. Kérjük, töltsd újra az oldalt az újrapróbáláshoz.`,
  _ = `Az összekapcsolt elemlista %1$s elemét nem sikerült betölteni az Áruházból, valószínűleg azért, mert le vannak tiltva, vagy már nem értékesítettek. A címkéik nem lettek újraépítve, így kieshetnek a címkére szűrt szakaszokból (ha le vannak tiltva stb., akkor a szokásos módon folytathatod a munkát): %2$s. `,
  _ = `Esemény kezdődátuma`,
  _ = `Bejelentés dátuma`,
  _ = `Most - Amikor az esemény közzé lesz téve`,
  _ = `Most - Amikor a bejelentés közzé lesz téve`,
  _ = `Jövőben - Esemény ütemezése jövőbeni kezdetre`,
  _ = `Jövőben - Bejelentés ütemezése jövőbeni megjelenésre`,
  _ = `Ütemezett kezdődátum`,
  _ = `Ütemezett közzétételi dátum`,
  _ = `Az eseményt a kezdődátum előtt is láthatóvá teheted, ha szeretnéd tudatni a játékosokkal, hogy közeleg az esemény, és lehetővé akarod tenni, hogy feliratkozhassanak az értesítésekre.`,
  _ = `A bejelentést a kezdődátum előtt is láthatóvá teheted, ha szeretnéd tudatni a játékosokkal, hogy közeleg az eseményed, és lehetővé tenni, hogy feliratkozhassanak értesítésre.`,
  _ = `Esemény végdátuma`,
  _ = `Az ilyen jellegű eseményeknek általában van végdátuma.`,
  _ = `Válassz befejezési dátumot, hogy a Steam tudja, mikor jelezze eseményed véget. Ez lehetővé fogja tenni a Steamnek, hogy előnyben részesítse más, frissebb vagy jelenleg aktív eseményeid mutatását.`,
  _ = `Befejezés a kezdési dátum óta eltelt bizonyos idő után.`,
  _ = `A befejezési időt %1$s időpontra kerekítjük.`,
  _ = `Végdátum`,
  _ = `Az eseményidőpontok a szerkesztőben a te helyi időzónádban láthatók. A Steames vásárlók szintén a saját időzónájukban fogják látni azokat.`,
  _ = `Befejezés megadott időpontban...`,
  _ = `Az időket saját helyi időzónád szerint add meg. Ezek az idők automatikusan át lesznek átalakítva a megtekintők helyi idejére, és úgy lesznek megjelenítve.`,
  _ = `Automatikus emlékeztetők`,
  _ = `Egy esemény kezdetét jövőbeni időpontra állítva, ÉS hamarabb láthatóvá téve a rajongóidnak, lehetővé teszed, hogy feliratkozzanak az esemény kezdetének értesítésére. A Steam automatikusan leküldéses értesítést, illetve e-mailt fog küldeni a Steam felhasználóknak a beállításaik alapján.`,
  _ = `Ez a teszt csak a te fiókodra fogja elküldeni, ha van hitelesített e-mail-címed, vagy telepítve van a(z) %1$s.`,
  _ = `Steam mobilalkalmazás`,
  _ = `Eseményértesítés tesztelése`,
  _ = `* A funkció le van tiltva, mert az esemény nem a jövőbe van ütemezve.`,
  _ = `Társított AppID`,
  _ = `Társítasz AppID-t ehhez az eseményhez?`,
  _ = `Lehetővé teszi AppID társítását az eseményhez. Ez automatikusan felhozza az áruházi kapszulát a megjelenített eseményleírás alján. Szükség szerint ellát alkalmazásinformációkkal más olyan widgeteket, mint a közvetítési vagy ütemezési widget.`,
  _ = `Kezdete`,
  _ = `Vége`,
