  _ = `Bejelentés tartalma`,
  _ = `Vizuális szerkesztő használata`,
  _ = `Buildhez társítás...`,
  _ = `Adj hozzá hivatkozást konkrét builddel ehhez a bejegyzéshez, hogy az megjelenjen frissítésjegyzékként a Steam „Letöltések” ablakában.`,
  _ = `Ez az esemény nincs buildhez társítva`,
