  _ = `Ez az esemény a(z) %2$s ág %1$s buildjéhez van társítva`,
  _ = `Ág kiválasztása`,
  _ = `Válaszd ki, melyik ághoz akarod társítani ezt az eseményt, és ez ezt az eseményt az ág jelenlegi buildjéhez fogja társítani. El is távolíthatod egy esemény buildhez kapcsolását a „Ne társítsa ezt az eseményt buildhez” lehetőséggel.`,
  _ = `Default ág - %1$s build (%2$s)`,
  _ = `%1$s - %2$s build (%3$s)`,
  _ = `Ne társítsa ezt az eseményt buildhez`,
  _ = `Verzióelőzmények megnézése (utolsó 100 bejegyzés)`,
  _ = `Esemény visszaállítása erre a verzióra`,
  _ = `Biztosan vissza akarod állítani ezt az eseményt a kiválasztott verzióra? Ez el fogja vetni a nem mentett változtatásokat, és visszaállítja az eseményt a korábbi állapotra.`,
  _ = `Módosította: %1$s`,
  _ = `Esemény visszaállítása előző verzióra`,
