  _ = `Alább található az eseményen végrehajtott legutóbbi változtatások listája. Kiválaszthatsz egy verziót a visszaállításhoz, ha változtatásokat akarsz visszavonni.`,
  _ = `Különbség az előzőhöz képest`,
