  _ = `Add meg az esemény alcímét (elhagyható)`,
  _ = `Add meg itt az esemény leírását`,
  _ = `Írd be ide a szövegszakaszt`,
  _ = `Közvetítéshez kapcsolódó`,
  _ = `Ha a Steames vásárló a fiókbeállításaival elrejti a közvetítést az Áruházban, akkor ezt a szakaszt is rejtse el, mivel a megjelenítése a közvetített tartalomhoz kapcsolódik.`,
  _ = `Elrejtés letiltott közvetítésnél`,
  _ = `Láthatósághoz kapcsolódó`,
  _ = `Ha a megtekintő nincs bejelentkezve, gátolja meg e szakasz megjelenését az oldalon.`,
  _ = `Elrejtés, ha a felhasználó ki van jelentkezve`,
