  _ = `Kép kiválasztása`,
  _ = `HTML importálása`,
  _ = `Importálás HTML-ből`,
  _ = `Importálás HTML-ből. HTML-edet automatikusan átalakítja a Steam formázási elemeire.`,
  _ = `Ide írj vagy illessz be HTML-t.`,
  _ = `Sortörések megőrzése`,
  _ = `HTML-ben a sortöréseknek általában nincs hatásuk, de BBCode-ban üres sorokként fognak megjelenni. Ha <p> vagy <br> tageket használtál, ezt ne jelöld be. Ha általában olyan blogprogramot használsz, mely automatikusan hozzáadja a <br> tageket a sorvégekhez, valószínűleg jobb, ha ezt bejelölöd.`,
  _ = `Konvertálás BBCode-ba:`,
