  _ = `Nem lehet kategóriát váltani`,
  _ = `Eseményeid és bejelentéseid, beleértve a folyamatban lévő vázlatokat és a közzétett eseményeket.`,
  _ = `Nem közzétett`,
  _ = `Szerkesztés`,
  _ = `Klónozás`,
  _ = `Megnézés`,
  _ = `Előnézet`,
  _ = `Közzététel`,
  _ = `Ez törölni fogja ezt az eseményt.`,
  _ = `Megnyitás`,
  _ = `Új esemény vagy bejelentés létrehozása`,
  _ = `Vázlatok (rejtett, nincs közzétéve)`,
  _ = `Ez azon események listája, amelyek mentésre kerültek, de még szerkeszted őket. Vásárlók számára nem láthatók, csak játékod közösségi csapatának többi tagja látja őket. Amikor elkészültek, közzé kell tenned ezeket az eseményeket, hogy láthatóvá váljanak a Steames vásárlóknak.`,
  _ = `Ütemezett események (rejtett, közzétett)`,
  _ = `Ez azon események listája, amelyek elő vannak jegyezve és készen állnak automatikusan láthatóvá válni a megadott jövőbeni időpontban. Továbbra is szerkesztheted ezeket az eseményeket, ha frissítened kell őket.`,
  _ = `Listázatlan események (közzétett, közvetlen hivatkozással látható)`,
  _ = `Az ilyen események csak az eseményhez közvetlen hivatkozással rendelkezőknek láthatók. Nem szerepelnek semmilyen listán, és nincsenek automatikusan hivatkozva semmilyen eseményrendszerből.`,
  _ = `Nyilvánosan látható események (látható, közzétett)`,
  _ = `Ez azon események listája, amelyeket minden Steam felhasználó láthat különféle helyeken az Áruházban, a Közösségben és a Steam Könyvtárában. Továbbiak betöltéséhez görgess lejjebb.`,
  _ = `Kiemelt`,
  _ = `Ez az esemény „kiemeltként” van megjelölve. A legutóbbi „kiemelt” esemény hangsúlyosabban fog megjelenni a játékosoknak a játékod könyvtároldalának tetején.`,
  _ = `Közelgő`,
