  _ = `Nincsenek nyilvánosan látható események ehhez a játékhoz.`,
  _ = `Minden nyilvános esemény betöltve és fentebb látható`,
  _ = `Hibába ütköztünk további események és bejelentések lekérésekor. Próbáld újra később.`,
