  _ = `Az e-mailen végzett változtatások nincsenek mentve. Kérjük, mentsd a változtatásokat az e-mail előnézet aktiválása előtt.`,
  _ = `E-mail küldése a fiókodhoz társított „%1$s” címre? Ha ez helytelen, itt frissítsd az e-mail-címedet: %2$s`,
