  _ = `Láthatósági összegzés`,
  _ = `Beállításaid alapján, eseményed vagy bejelentésed az alábbi helyeken fog megjelenni:`,
  _ = `Alapértelmezett helyek`,
  _ = `Választható helyek`,
  _ = `Megjelenések`,
  _ = `Áruház: a játékod áruházi oldalán`,
  _ = `Ez az esemény játékod áruházi oldalának „Hírek és események” szakaszában fog megjelenni.`,
  _ = `Ez a szám az áruházi oldalad látogatóinak becsült számát tükrözi azon időszak alatt, amíg az esemény látható lesz.`,
  _ = `Áruház: a „Nemrég frissített játékok” oldalon`,
  _ = `Ha frissítési láthatósági kört használsz ezen esemény közzététele után, ez az esemény meg fog jelenni a „Nemrég frissített” oldalon azon játékosoknak, akiknek megvan vagy kívánságlistán van a játékod.`,
  _ = `Ez a szám mutatja, hány felhasználónak van meg, vagy van kívánságlistán a játékod és láthatja azt a „Nemrég frissített” oldalon.`,
  _ = `Hírek: a játékod Hírek oldalán`,
  _ = `Ez az esemény meg fog jelenni a hírek listájában, ami a játékod áruházi oldalán levő „Kapcsolódó hírek olvasása” hivatkozásra kattintva érhető el.`,
  _ = `A szám a játékod hírek oldalának becsült forgalma.`,
  _ = `Közösség: a játékod közösségközpontjában`,
  _ = `Ide tartozik a játékod fő központoldala, valamint a „Hírek” fül, és az áruházi oldaladról hivatkozott „Bejelentések” nézet.`,
  _ = `Közösség: a játékodat követő játékosok barátaktivitás-listájában`,
  _ = `Ez az esemény megjelenhet a játékodat követő játékosok aktivitáslistájában.`,
  _ = `A mutatott szám a játékodat követő játékosok száma.`,
  _ = `Jövőbeni:`,
  _ = `Könyvtár: a Steam Könyvtár főoldalon (lehetőségként)`,
  _ = `Játékosaid láthatják ezt az eseményt a Könyvtár főoldaluk tetején, attól függően, hány játéka van egy adott játékosnak, és az egyes bejelentések vagy frissítések relatív prioritása alapján.`,
  _ = `(Moderálásig függőben)`,
  _ = `Könyvtár: kiemelt szalagkép játékod Könyvtári oldalán`,
  _ = `Ha megadsz kiemelt szalagképet, eseményed / bejelentésed megjelenhet a Játék gomb alatt a játékod részletek oldalán a Steam Könyvtárban.`,
  _ = `Könyvtár: játékod oldalán a játékosok Steam Könyvtárában`,
  _ = `Eseményed meg fog jelenni játékoldalad aktivitás szakaszában játékosaid Steam Könyvtárában.`,
  _ = `Azon játékosok száma alapján, akik rendelkeznek a játékoddal és láthatják Steam Könyvtárukban.`,
  _ = `A Műhely-oldalon`,
  _ = `Közzéteheted ezt az eseményt / bejelentést játékod Steam Műhelyében is. Ennek bekapcsolásához válts a „Beállítások” fülre és válaszd a „Közzététel a Műhelyedben is” lehetőséget. Alapesetben a játékesemények / bejelentések nem jelennek meg a Műhely részben.`,
  _ = `Vásári Steam termékoldal szalagkép`,
  _ = `A termékoldali szalagkép %1$s és %2$s között látható.`,
  _ = `Megadhatsz egy vásári szalagképet a Vásár fülön, ami lehetővé teszi, hogy a kiemelt játékok visszahivatkozzanak a vásári oldalra a megadott kép megjelenítésével Steam termékoldaluk tetején. Ez olyan Steames vásárlóknak hasznos, akik egy konkrét játékkedvezményt a kívánságlista e-mailen vagy az áruház böngészésén keresztül fedeznek fel, hogy így tudomást szerezzenek a nagyobb vásári eseményről is. E szalagképek csak eseményed kezdetétől a végéig, vagy legfeljebb két hétig láthatók, amelyik hamarabb bekövetkezik. Az esemény kezdő és végidőpontja a Beállítások fülön van megadva.`,
  _ = `Értesítés: e-mailben a játékodat, fejlesztődet vagy kiadódat követő játékosoknak`,
  _ = `Ebbe beletartozik az e játékhoz társított fejlesztői, kiadói és franchise oldalak összes követője.`,
  _ = `A következő fejlesztői, kiadói vagy franchise oldalaknak nincs látható készítői kezdőoldala. Létrehozása segítene vásárlóidnak átlátni kínálatodat, és lehetőséget adnak nekik, hogy tudomást szerezzenek eseményeidről és játékmegjelenéseidről: %1$s`,
  _ = `Hírek: a játékosok személyre szabott eseménynaptára`,
  _ = `Ez az esemény a személyre szabott hírközpontban jelenik meg azon játékosoknak, akiknek megvan könyvtárukban, illetve kívánságlistájukhoz adták vagy követik a játékod.`,
  _ = `Értesítés: mobilos leküldéses értesítés a feliratkozott játékosoknak`,
  _ = `Azon játékosok száma, akik kimondottan feliratkoztak emlékeztetőre erről az eseményről (letöltöttek egy külső naptárlistát vagy az esemény követése mellett döntöttek).`,
  _ = `játékos kap e-mailt`,
  _ = `Azon e-mailek becsült száma, melyek tartalmazni fogják ezt az eseményt. Rendszeresen készítünk egy összefoglalót a céleseményekről minden vásárlónak. Ez függ az egyes vásárlók e-mail-értesítési és kommunikációs beállításaitól.`,
  _ = `játékos kapja meg marketing üzenetben`,
  _ = `Azon játékosok becsült száma, akik látni fogják ezt az eseményt személyre szabott Steam kliens marketing üzenetükben. Ez egy felugró ablak, ami a Steam asztali kliensének indításakor jelenik meg, és fontos Steames akciókról és érdekes eseményinformációkról tudósít.`,
  _ = `játékos mellőzte ezt az eseményt`,
  _ = `Azon játékosok száma, akik kifejezetten az esemény mellőzését választották.`,
  _ = `Eseménybetöltési hiba`,
  _ = `Dokumentáció megnézése`,
  _ = `Jelentős frissítés marketingüzenetének felülvizsgálata`,
  _ = `Miután az esemény elkészült, és nincs szükség további változtatásokra, kérjük, küldd be felülvizsgálatra marketingüzenetben való felhasználáshoz. Amint elkészült, nyugodtan közzéteheted a jelentős frissítési eseményt. Kérjük, hagyj legalább %1$s munkanapot a felülvizsgálatra és jóváhagyásra.`,
  _ = `Hozd létre a következő jegyet a felülvizsgálati folyamat megkezdéséhez.`,
  _ = `Felülvizsgálati jegy létrehozása`,
  _ = `Jegy beküldve. Kérjük, tekintsd át és frissítsd az információkat <1>itt</1>.`,
  _ = `Összegzés`,
  _ = `Láthatóság kezdete`,
  _ = `Ez a közzététel után a legtöbb helyen azonnal látható lesz.`,
  _ = `Vedd figyelembe, hogy az új közzétételeket moderátorcsapatunk időrendi sorrendben vizsgálja felül. Előfordulhat több mint egy órás késés is, mielőtt a hírek vagy események megjelennek a Steam Könyvtárban. A meglévő közzétételek bármilyen szerkesztése visszahelyezi azokat a moderálási sorba.`,
  _ = `Vagy egy meglévő esemény tartalmának cseréje`,
  _ = `Ritka. Ez lehetővé teszi, hogy frissítéseket készíts elő egy „vázlat” eseményben, majd egy meglévő, közzétett esemény tartalmát ezen esemény tartalmára cseréld. Ez az esemény el fog tűnni, és a tartalma le fogja cserélni a célzott közzétett eseményt. A célzott esemény típusa és láthatósági beállításai nem lesznek frissítve.`,
  _ = `Ez az esemény innen lett klónozva: „%1$s”`,
  _ = `Eredeti esemény lecserélése`,
  _ = `Ezen esemény tartalma le fogja cserélni annak az eseménynek a tartalmát, amelyikből ez eredetileg klónozva volt.`,
  _ = `Megjegyzés: Az eredeti eseménynek közzétettnek és láthatónak kell lennie. Nem tudjuk lecserélni, amíg az nyilvánosan nem látható.`,
  _ = `E művelet azonnali. Le fogja cseréni a célesemény tartalmát, és azonnal látható lesz a Steam felhasználóknak. Az aktuális esemény fel fog használódni e művelet során.`,
  _ = `A célesemény neve: %1$s`,
