  _ = `Közvetítés előtti tartalom`,
  _ = `Elavult: A VOD-folyamat mostantól ki van kapcsolva; hátrahagyva arra az esetre, ha régi videót kéne használnunk. Ez a videó fog megjelenni a közvetítésmegjelenítőben a normál műsor előtt. A VOD-nek nyilvános engedéllyel kell rendelkeznie (ez más, mint a kiadási állapot).`,
