  _ = `Szűrés az e fülön látható szakaszokra`,
  _ = `Átmenetileg csak azokat a szakaszokat mutatja a szerkesztőben, amelyek láthatók e fülön. Ez a funkció csak szerkesztéskor működik.`,
  _ = `Fül elrejtése`,
  _ = `Fülláthatóság`,
  _ = `Beállítás annak meghatározására, hogy egy adott felhasználó láthatja-e a fület a vásári oldalon.`,
  _ = `Bekapcsolod az ország szerinti láthatósági beállításokat?`,
  _ = `Ország-engedélylista`,
  _ = `Ez a kétbetűs országkódok vesszővel tagolt listája. Csak az engedélyezett országokban fog megjelenni.`,
  _ = `Ország-tiltólista`,
  _ = `Ez a kétbetűs országkódok vesszővel tagolt listája. Csak a tiltott országokban fog megjelenni.`,
  _ = `Bekapcsolod a csomagláthatósági beállításokat?`,
  _ = `Csomagengedélyezési lista`,
  _ = `Ez egy vesszővel elválasztott csomagazonosítókat tartalmazó lista. Ez a fül csak akkor fog megjelenni, ha a megtekintő birtokolja a felsorolt csomagok egyikét.`,
  _ = `Bekapcsolod a hardverhasználat láthatósági beállításokat?`,
  _ = `Ez a fül csak akkor jelenik meg, ha a látogató használta ezen hardverek valamelyikét. Ha ezek közül bármelyik be van jelölve, akkor ez a rész kijelentkezett felhasználóknak nem lesz látható.`,
  _ = `Használt hardver engedélyezési lista`,
  _ = `Jelenlegi fülek`,
  _ = `Minden fül elemek elnevezett gyűjteményét definiálja, ami csak azon elemek mutatására fogja szűrni a következő szakaszokat.`,
  _ = `A fülek egyfajta szűrők, amelyek szabályozzák, mely szakaszok jelenjenek meg. Adj meg itt füleket, majd az egyes szakaszokhoz lépve válaszd ki, hogy az adott szakasz mely füleken jelenjen meg. Alapértelmezés szerint a szakaszok minden fülön láthatók.`,
  _ = `Válassz egy fület itt, hogy csak azok a szakaszok jelenjenek a szerkesztőben, amelyek láthatók a fülön. Ez a funkció csak szerkesztéskor működik.`,
  _ = `%1$s fül`,
