  _ = `Kiválasztási / kiemelési szín`,
  _ = `Felülírja a fülek alapértelmezett kiválasztási és kiemelési színét. Az alapértelmezetthez való visszatéréshez távolítsd el a beállítást.`,
  _ = `Füllel szűrt elemlista`,
  _ = `A következő elemek szűrőként működnek, és az ezeket követő szakaszokban csak az e listán szereplő elemek jelenhetnek meg, amikor ez a fül ki van választva.`,
  _ = `%1$s - Elemek: %2$s`,
  _ = `%1$s - Összes elem mutatása`,
  _ = `Ez a fül úgy van beállítva, hogy mutassa az összes elemet a következő szakaszokban. Alább kattintva azonban létrehozhatsz egy elemlistát, és akkor az ezen a listán szereplő elemek fognak megjelenni a következő szakaszokban, amikor ez a fül aktív.`,
  _ = `Szűrt elemek szerkesztése`,
  _ = `Kiválasztott fül háttérkép (opcionális)`,
  _ = `Lehetővé teszi egy fülenkénti háttérkép megadását, ami a fül kiválasztásakor jelenik meg. A kép végigér a fülsávon a képernyő tetején.`,
  _ = `Megjegyzés: a szűrők a kapszulára mutatáskor automatikusan hozzá fogják adni a Deck-kompatibilitási panelt.`,
