  _ = `Megjegyzés: a szűrők automatikusan elrejtik ezt a fület azon vásárlók elől, akik nem engedélyezték „Csak felnőtteknek” tartalom mutatását.`,
  _ = `Megjegyzés: a szűrők automatikusan el fogják távolítani a nem közelgőkkel kapcsolatos füleket az Elemböngészőből.`,
  _ = `Ugráslista`,
  _ = `Az ugráslista a fülek alatt jelenik meg, és segít a fül alatti szakaszokhoz való gyors navigálásban; akkor hasznos, amikor egy fülnek sok szakasza van.`,
