  _ = `Címkenév szóközök nélkül`,
  _ = `Ha ez be van állítva, az összes játékot (azokat is, amelyek ebben a vásárban nincsenek kifejezetten megjelenítve) tartalmazni fogja a körforgó. A felhasználókat érdeklő (birtokolt, kívánságlistázott, követett) játékok eseményeit részesítjük előnyben, majd másodsorban a legkelendőbbekét.`,
  _ = `Betöltendő események maximális száma`,
  _ = `Legfeljebb hány eseményt hívjon le a szerverről. Legalább 15 választását javasoljuk. A maximális mennyiség 100.`,
  _ = `Alapértelmezetten %1$s eseményt mutat.`,
  _ = `Események dátum-/időtartománya`,
  _ = `Ha nincs beállítva, a vásári esemény kezdő- és végdátumát használjuk, azonban az eseményekhez be lehet állítani a vásári eseményen túlnyúló időtartományt is, ebben az esetben ezeket a mezőket meg kell adni.`,
  _ = `Kezdődátum szerinti fordított sorrendben mutatás (a legutóbbival kezdve)`,
  _ = `Ha be van jelölve, az események a kezdődátumuktól kezdve fordított sorrendben jelennek meg.`,
