  _ = `Kívánságlista`,
  _ = `A felhasználó kívánságlistáján lévő játékok eseményeinek mutatása (nem korlátozódik a vásári oldalra vagy a tartalomközpontra, de fülek vagy szakaszszűrők vannak alkalmazva).`,
  _ = `Könyvtár`,
