  _ = `Interaktív Ajánló`,
  _ = `Az Interaktív Ajánló (IA) által a felhasználónak javasolt játékok eseményeinek mutatása (nem korlátozódik a vásári oldalra vagy a tartalomközpontra, de fülek vagy szakaszszűrők vannak alkalmazva).`,
