  _ = `A Cím/Fejléc szakasz vagy szöveget, vagy képet tud megjeleníteni, és az azt követő tartalom címkéjeként szolgál. A Fülek szakasszal együtt használva opcionálisan alfül lehetőségeket jeleníthet meg automatikusan, ha kettő vagy több fül van jelen. A fül működéséhez alább szükséges egy rövid név.`,
  _ = `Megjelenítés típusa`,
