  _ = `Aktív lépés színe`,
  _ = `Navigációs útvonalszín`,
  _ = `Körforgó navigációs útvonal stílusok`,
  _ = `Kerekített stílusok`,
  _ = `Kerek stílusok`,
  _ = `Négyzetes stílusok`,
  _ = `Premier esemény címkeszín`,
  _ = `Premier esemény háttérátmenet (bal)`,
  _ = `Premier esemény háttérátmenet (jobb)`,
  _ = `Premier esemény fókusz háttérátmenet (bal)`,
