  _ = `jobb felül`,
  _ = `balra középen`,
  _ = `középen`,
  _ = `jobbra középen`,
  _ = `bal alul`,
  _ = `középen lent`,
  _ = `jobb alul`,
  _ = `Méretezés`,
  _ = `Szabályozza a logó méretét a háttérhez képest.`,
  _ = `Szövegméretezés`,
  _ = `Lehetővé teszi a szöveg által kitöltött hely nagyságának beállítását %1$s és %2$s között, %3$s alapértékkel.`,
  _ = `Méretezés alaphelyzetbe`,
