  _ = `Húzz ide statikus képeket (.png/.jpg) (max. 20 MB).`,
  _ = `Kikapcsolja a mobilváltozatot, és törli a beállításait.`,
  _ = `A mobilváltozat egy elhagyható beállítás, amely lehetővé teszi e rácsos média teljes testreszabását mobil elrendezésben megjelenítéskor. Ez lehetővé teszi eltérő szöveg, grafika és vezérlők megadását a mobilmegjelenítéshez.`,
  _ = `Biztosan ki akarod kapcsolni a mobilváltozatot? Ez eltávolítja az adatok mobilváltozatát, ami nem vonható vissza.`,
  _ = `Kikapcsolja a táblagépváltozatot, és törli a beállításait.`,
  _ = `A táblagépváltozat egy elhagyható beállítás, amely lehetővé teszi e rácsos média teljes testreszabását táblagépes elrendezésben, Steam Decken vagy hasonló készüléken megjelenítéskor. Ez lehetővé teszi eltérő szöveg, grafika és vezérlők megadását a táblagépes megjelenítéshez.`,
  _ = `Biztosan ki akarod kapcsolni a táblagépváltozatot? Ez eltávolítja az adatok táblagépes változatát, ami nem vonható vissza.`,
