  _ = `Kitűzőhaladás-szerkesztő`,
  _ = `Definiáld a vásári esemény kitűző-haladását, és használd az elérhető [badgeNextLevel eventbadgeid=#] BBCode-ot a jelenlegi állapot kitöltésére.`,
  _ = `Kitűző neve`,
  _ = `Kitűző kezdeti leírása`,
  _ = `Írd le a kitűző megszerzéséhez szükséges alapvető mechanizmust azon vásárlóknak, akik még nem kapták meg. Ez a be nem jelentkezett felhasználóknak is meg fog jelenni. Ők meg lesznek kérve, hogy a kitűzővel haladáshoz jelentkezzenek be.`,
  _ = `Kitűzőhaladás-útmutató`,
  _ = `Most, hogy a felhasználónak megvan az alap kitűző, ez további segítséget adhat a kitűző következő szintre fejlesztéséhez.`,
  _ = `Kitűzőhaladás-útmutató – Maximális szint elérve`,
  _ = `Ez a maximális kitűzőszint, amit az átlag felhasználó észszerű módon vélhetőleg el fog tudni érni. Az útmutatás kitérhet a szintnövelés folytatásának más módjaira, ha van arra lehetőség.`,
  _ = `Kitűzőszintek és URL-ek`,
  _ = `Szint: `,
  _ = `Kitűzőkép URL`,
  _ = `Az elem valószínűleg már létezik a közösségben és 160 x 160 képpont méretűnek kell lennie. A képre hivatkozáshoz használhatod a(z) {IMG_URL}/badges/... rövid formát.`,
  _ = `(Opcionális) Szürke kitűzőkép URL`,
  _ = `Opcionális elem, ami ha be van állítva, a tényleges kitűző megszerzése ELŐTT fog megjelenni a felhasználónak. Ez akkor hasznos, ha a megszerzés előtt el akarsz rejteni bizonyos részleteket a kitűzőről. Az elemnek 160 x 160 képpont méretűnek kell lennie.`,
  _ = `Szint- és URL-sor megadása`,
  _ = `Felhasználói kitűzőazonosító (eseményspecifikus)`,
  _ = `Kitűzőszint az ezen a vásári oldalon lévő felfedezési várólista befejezésekor lesz megadva.`,
  _ = `Ez elvárja, hogy a felfedezési várólista már létezzen az áruházi oldalon. A kitűző dinamikusan frissül egy várólista befejezésekor, és átküldi a kitűzőmegadásokat a felfedezési várólista összefoglaló oldalára.`,
  _ = `Küldetéshaladás-szerkesztő`,
  _ = `Meghatároz egy szakaszt, amely különböző BBCode-tartalmakat jeleníthet meg a küldetéshaladás alapján.`,
  _ = `Ha IGAZ, csak a zárt ajtót mutatja az előző kinyitása után.`,
  _ = `Küldetéshaladás-szakaszok`,
  _ = `Küldetésszakasz hozzáadása`,
  _ = `Küldetésszakaszt megelőzően`,
  _ = `Küldetési ajtó index - %1$s`,
  _ = `Küldetésszakasz`,
  _ = `Feladat befejezése előtti állapot leírása (zárt ajtó állapot)`,
  _ = `Feladat befejezése utáni állapot leírása (nyitott ajtó állapot)`,
  _ = `Opcionálisan adj hozzá BBCode-ot alább, amely csak akkor jelenik meg, miután a felhasználó teljesítette a küldetést.`,
  _ = `Siker utáni üzenet szerkesztése`,
  _ = `Küldetésjutalom-polcszerkesztő`,
  _ = `Szerkesztő a virtuális tárgyak jutalomeseményeinek összekötésére, és a felhasználónak megjelenítendő konkrét jutalmak kiválasztására. Be tudjuk tölteni az elérhető jutalmakat, és ki tudjuk választani, mely jutalmak jelenjenek meg a listán.`,
  _ = `Virtuális jutalomesemény azonosítója`,
  _ = `Például: k_EVirtualItemRewardEvent... érték`,
  _ = `Legutóbb szinkronizálva: `,
