  _ = `Tárgycsoport`,
  _ = `A csoport, amihez e tárgy tartozik. Egy ajtó kinyitása egy tárgyat ad minden általa lefedett csoportból, tehát ha egy csoportban egynél több tárgy van, csak egy, véletlenszerűen választott tárgyat ad. Adj mindegyik tárgynak saját csoportot, hacsak nem alternatívának szánod őket.`,
