  _ = `Tárgyak hozzáadása a jutalmakhoz`,
  _ = `Megjegyzés: Ha ez egy Pontboltban felveendő tárgyhoz van, hagyd a tárgycsoportot nullán. E mechanizmus csak a nullás csoportot olvassa, és nem kapcsolódik az alábbi ajtójutalmakhoz. `,
