  _ = `Virtuális tárgyjutalom inaktívként jelölése`,
  _ = `Ez megakadályozza, hogy a felhasználók megkapják e tárgyat. A már megkapott tárgyakat nem távolítja el, csak azt akadályozza meg, hogy a jövőben ehhez az eseményhez, illetve minijátékhoz meg lehessen kapni ezt a tárgyat. Biztosan ezt akarod tenni?`,
