  _ = `Nyers változat szerkesztése`,
  _ = `Lehetővé teszi az e vásárhoz kapcsolt elemek listájának közvetlen szerkesztését. Ez használható importálásra vagy exportálásara olyan alkalmazásokkal, mint az Excel, vagy gyorsan nagy változtatások végrehajtására az elemlistán.`,
  _ = `Egyedi jelölők`,
  _ = `Lehetővé teszi e vásárhoz a kapcsolt elemek listájának közvetlen szerkesztését és a csak a vásári elemeken levő egyedi jelölőgyűjtemények importálását és exportálását. Ez elsősorban külső táblázatban kezelt egyedi jelölőválaszték importálására szolgál, az elemek többi jelölőjének módosítása nélkül. Továbbá, e párbeszédpanelen keresztül részhalmaz is importálható, mivel nem fogja eltávolítani a nem felsorolt elemeket.`,
  _ = `Importálás a feliratkozási oldalról`,
  _ = `Megnyit egy párbeszédpanelt, amely lehetővé teszi az összes alkalmazás importálását és a kapcsolt elemlistába húzását egy feliratkozási oldalról.`,
  _ = `Elemek szinkronizálása`,
  _ = `Demójelölők szinkronizálása`,
  _ = `Ez végigmegy minden kapcsolt elemen, és HasDemo jelölőt ad minden alkalmazáshoz, amelynek van demója, azokról pedig eltávolítja, amelyeknek nincs.`,
  _ = `Szinkronizálás`,
  _ = `Ez lehetővé teszi különféle jelölők és más adatok szinkronizálását a kapcsolt elemek és egyéb források között.`,
  _ = `Demójelölők szinkronizálása`,
  _ = `Automatikus jelölők szerkesztése`,
  _ = `Írj be jelölőnevet`,
  _ = `Ez azon jelölő neve, ami azokhoz a kapcsolt elemekhez lesz alkalmazva, melyek megfelelnek a társított szűrőnek.`,
  _ = `Elemszűrő szerkesztése (%1$s szűrő)`,
  _ = `Elemszűrő szerkesztése (%1$s szűrő) (%2$s kiszűrve)`,
  _ = `Ez lehetővé teszi olyan szűrő beállítását, amely minden kapcsolt elemre alkalmazva lesz a szakaszokhoz való figyelembevétel előtt. Ezt használhatod például olyan játékok kiszűrésére, amelyeknek nincs demója, vagy van egy általad választott jelölője.`,
  _ = `Felfedezés`,
  _ = `Lehetővé teszi a szűrőeszköz használatát a jelenleg konfigurált kapcsolt elemek felfedezésére annak kiderítéséhez, hogy hány elem felel meg különféle szűrőknek, vagy mely jelölők vannak hozzájuk rendelve.`,
  _ = `Csoportos szerkesztés`,
  _ = `Lehetővé teszi a kapcsolt elemek csoportos szerkesztését. Megadható egy elemlista, majd csoportosan jelölők adhatók hozzájuk vagy távolíthatók el.`,
  _ = `Automatikus jelölők`,
  _ = `Automatikus jelölők létrehozását teszi lehetővé, ami egy szűrő, amely alkalmazza a megnevezett jelölőt bármely egyező kapcsolt elemre.`,
