  _ = `Jelölőelőtag`,
  _ = `A feliratkozási oldal által megadott jelölőkhöz csatolandó előtag. Ez lehetővé teszi, hogy például a feliratkozási oldalon meghatározott „Akció” eltérjen az áruházi oldalon lévő „Akciótól”.`,
  _ = `Demók szükségesek`,
  _ = `Amikor ez be van jelölve, csak olyan alkalmazásokat fog átengedni, amikhez van demó társítva.`,
  _ = `Alkalmazások betöltése a feliratkozási oldalról`,
  _ = `Áruházi definíciók betöltése az áruházi oldallal nem rendelkező alkalmazások kiszűréséhez`,
