  _ = `Válassz kedvezményeseményt.`,
  _ = `Görgess le, vagy írj be nevet a keresés megkezdéséhez.`,
  _ = `Kedvezményesemény-lista betöltése`,
  _ = `Kedvezményesemény alkalmazás- és csomagrészleteinek betöltése`,
