  _ = `Népszerű`,
  _ = `A legnépszerűbb DLC-kkel rendelkező szülőalkalmazások előre sorolása. A népszerűséget az eladási rangsor határozza meg, így az alacsony rangsorú DLC-k esetleg nem jelennek meg.`,
