  _ = `Műszerfalhoz lépés`,
  _ = `Válassz egy vagy több feltöltendő fájlt címed és leírásod lokalizált szövegének importálásához. A fájlkiterjesztést használjuk annak megállapítására, hogy a fájl XML vagy CSV importálás. XML esetében API nyelvkódot használunk a fájlnév végén a kiterjesztés előtt, hogy meghatározzuk az XML-fájl tartalmának nyelvét. A CSV vagy XML exportálásával érdemes kezdened, biztosítva, hogy a megfelelő formátumot használod.`,
  _ = `A kiválasztott típus egyetlen fájljába exportálja a jelenlegi nyelvet. Az XML mindig egyetlen fájlt hoz létre az adott szerkesztő nyelvvel. A CSV az összes elérhető nyelvet fogja egyetlen fájlba exportálni.`,
