  _ = `Szerkesztés…`,
  _ = `Válassz itt beállításokat e GYIK láthatóvá tételéhez a kívánt területen. A láthatósághoz egy, a kért nyelven vagy a területnek megfelelő másodlagos nyelven közzétett verzió is szükséges.`,
  _ = `A GYIK területi láthatósága e párbeszédpanelen változtatható meg. Ha a dokumentum nem látható, akkor még akkor sem hozzáférhető, ha közzé van téve.`,
