  _ = `Hozz létre egy új találkozócsoportot, amely egy egyedi ajánlat, például „Kávészünet”. Mindegyik csoport több találkozóval rendelkezhet, amely egy „Csak egyet válassz” lehetőségként lesz bemutatva a partnereknek.`,
