  _ = `+ Másik találkozó hozzáadása`,
  _ = `Találkozóbeállítások`,
  _ = `Találkozóbeállítások szerkesztése`,
  _ = `Találkozó címe`,
  _ = `Találkozó leírása`,
  _ = `Dátummegjelenítési formátum`,
  _ = `Mindig csendes-óceáni idő szerint add meg, hogy mikor lesz az esemény. Ezután válaszd ki, milyen formátumban kívánod megjeleníteni.`,
  _ = `Személyes részvételű eseményekhez – Időpont mutatása egy adott időzóna szerint`,
  _ = `Virtuális eseményekhez – Időpont mutatása a megtekintő időzónája szerint`,
  _ = `E találkozó törlése`,
  _ = `Találkozó kezdete`,
  _ = `Megjelenített kezdési időpont`,
  _ = `Megjelenített befejezési időpont`,
  _ = `Találkozó hossza (perc)`,
  _ = `Esemény maximális befogadóképessége`,
  _ = `További vendégek`,
  _ = `Legfeljebb ennyien tarthatnak a meghívottal.`,
  _ = `Új felhasználói szavazás létrehozása beágyazva ebbe az eseménybe, kérdés feltételéhez a közösségednek.`,
  _ = `Felhasználói szavazás létrehozása`,
  _ = `Felhasználói szavazás szerkesztése`,
  _ = `Mi a kérdés, amit felteszel a szavazáson?`,
  _ = `A szavazás az esemény láthatóvá válásakor azonnal elindul.`,
  _ = `A szavazás befejezése adott nap után`,
  _ = `A szavazás befejezése egy adott időpontban`,
  _ = `A saját időzónádat használja`,
  _ = `Ki szavazhat?`,
  _ = `Bármely bejelentkezett Steam felhasználó`,
  _ = `Steam felhasználók ezzel a játékkal a Könyvtárukban`,
  _ = `Legalább X játékidővel rendelkező Steam felhasználók`,
  _ = `Steam felhasználók, akik tagjai ennek a csoportnak`,
  _ = `Ki láthatja a szavazás eredményeit?`,
  _ = `Csak e csoport adminisztrátorai láthatják az eredményeket`,
  _ = `Csak azok láthatják az eredményeket, akik szavaztak`,
  _ = `Bárki megnézheti az eredményt a szavazás lezárása után`,
  _ = `Azok nézhetik meg, akik szavaztak, illetve a szavazás lezárása után mindenki`,
  _ = `Bárki bármikor megnézheti az eredményeket (alapértelmezett)`,
  _ = `Percben mért minimum játékidő`,
  _ = `Szavazás háttérképe (elhagyható)`,
  _ = `Feltölthetsz egy statikus képet, ami a szavazási kérdésed mögött jelenik meg, hogy az elkülönüljön az eseményedben. Kérjük, biztosíts egy legalább 800 képpont széles és 300 képpont magas képet.`,
  _ = `Nem sikerült megtalálni a szavazási modellt (%1$s). Kérjük, töröld és próbáld újra.`,
  _ = `Szavazási lehetőség hozzáadása`,
  _ = `Felhasználói szavazási lehetőség szerkesztése`,
  _ = `Írd be a lehetőséghez megjelenítendő szöveget`,
  _ = `+ További lehetőség hozzáadása`,
  _ = `Lehetőségek átrendezése`,
  _ = `Irányítani tudja a felhasználói szavazást meglátogató játékosnak megjelenített lehetőségek listájának sorrendjét.`,
  _ = `Ha be van állítva, minden megtekintőnek véletlenszerűsíti a sorrendet.`,
  _ = `%1$s SZAVAZAT`,
