  _ = `%1$s / %2$s tárgy összegyűjtve`,
  _ = `A Pontbolt felkeresése`,
  _ = `Kitűzőállapot megnézése`,
  _ = `%1$s / %2$s`,
  _ = `összegyűjtve`,
  _ = `Szerezd meg e tárgyakat ingyen`,
  _ = `Ingyenes tárgy küldetés: Steam felfedezési várólista`,
  _ = `Menj végig a Steam felfedezési várólistádon, hogy ingyenes matricákat szerezz.`,
  _ = `A várólistát megtalálod a kezdőoldalon, illetve bármelyik címke- vagy műfajoldalon. <1>Kattints ide</1> a várólistád felkereséséhez és a kezdéshez.`,
  _ = `Szerezd be e tárgyakat a Pontboltban`,
  _ = `Szerezd meg e kártyákat kitűzők készítésével vagy vásárlásokkal.`,
